param([string]$Project = "C:\Projects\xcliprank", [string]$RestoreBackup = "")
$ErrorActionPreference = "Stop"
$Project = [IO.Path]::GetFullPath($Project)
if (!(Get-Command node -ErrorAction SilentlyContinue)) { throw "Node.js is required. No source files changed." }
$tempDir = Join-Path ([IO.Path]::GetTempPath()) ("xclip-availability-curated-fix-" + [Guid]::NewGuid().ToString("N"))
[IO.Directory]::CreateDirectory($tempDir) | Out-Null
try {
  $bytes = [Convert]::FromBase64String("")
  $sha = [Security.Cryptography.SHA256]::Create()
  try { $hash = [BitConverter]::ToString($sha.ComputeHash($bytes)).Replace("-", "").ToLowerInvariant() } finally { $sha.Dispose() }
  if ($hash -ne "eeece1c2c80c1d2d0172cee68ad23652738200df436bcce87df0b3fabc7349dc") { throw "Embedded install.cjs checksum failed. No source files changed." }
  [IO.File]::WriteAllBytes((Join-Path $tempDir "install.cjs"), $bytes)
  $bytes = [Convert]::FromBase64String("")
  $sha = [Security.Cryptography.SHA256]::Create()
  try { $hash = [BitConverter]::ToString($sha.ComputeHash($bytes)).Replace("-", "").ToLowerInvariant() } finally { $sha.Dispose() }
  if ($hash -ne "712d3e3443f7d12cebdc1d7623426156372eaea00e6464a0ede5bdd9f6af3193") { throw "Embedded local-payload.json checksum failed. No source files changed." }
  [IO.File]::WriteAllBytes((Join-Path $tempDir "local-payload.json"), $bytes)
  & node (Join-Path $tempDir "install.cjs") $Project $RestoreBackup
  if ($LASTEXITCODE -ne 0) { throw "Installation/check failed. Read the error above." }
} finally {
  if (Test-Path $tempDir) { Remove-Item $tempDir -Recurse -Force }
}
